sys_ui_page.client_script:
function showConfirmationDialog() {
    document.getElementById('confirmationDialog').style.display = 'block';
}

function closeDialog() {
    document.getElementById('confirmationDialog').style.display = 'none';
}

function submitForm() {
    closeDialog(); // Hide dialog after clicking Yes

    var username = document.getElementById('username').value;
    var firstName = document.getElementById('firstName').value;
    var lastName = document.getElementById('lastName').value;
    var password = document.getElementById('password').value;
    var confirmPassword = document.getElementById('confirmPassword').value;
    var country = document.getElementById('country').value;
    var photo = document.getElementById('photo').files[0]; // Get file

    // Validate required fields
    if (username === '' || firstName === '' || lastName === '' || password === '' || confirmPassword === '') {
        alert('Please fill all required fields.');
        return;
    }

    // Check if passwords match
    if (password !== confirmPassword) {
        alert('Passwords do not match.');
        return;
    }

    // Create FormData object to send file
    var formData = new FormData();
    formData.append('sysparm_name', 'createUser');
    formData.append('username', username);
    formData.append('firstName', firstName);
    formData.append('lastName', lastName);
    formData.append('password', password);
    formData.append('country', country);
    if (photo) {
        formData.append('photo', photo);
    }

    var ga = new GlideAjax('UserCreationModel');
    for (var pair of formData.entries()) {
        ga.addParam(pair[0], pair[1]);
    }

    ga.getXML(updateResponse);
}

function updateResponse(response) {
    var result = response.responseXML.documentElement.getAttribute("answer");
    alert(result);

    if (result.includes('successfully')) {
        document.getElementById('userCreationForm').reset();
    }
}
